import React, { useContext, useEffect, useState } from "react";
import { useForm } from "react-hook-form";
import {
  getFromLocalStorage,
  setInLocalStorage,
  getFromWorkbookSettings,
  setInWorkbookSettings,
  ARBOR_CHAT_API,
} from "../taskpane";
import { TokenInput } from "./TokenInput";
import { ModelProviderSelect } from "./ModelProviderSelect";
import { HostOverrideInput } from "./HostOverrideInput";
import { DebugContext, LayoutContext } from "../context";
import store from "../../stores/store";
import Alert from "./Alert";
import { getQuota } from "../api/getQuota";
import { IconShieldHalf } from "@tabler/icons-react";

export type ApiKeyFormInputs = {
  apiKey: string;
  apiHost: string;
  disableCalculationOverride: boolean;
  modelProvider: "groq" | "openai";
  concurrency: number;
};

const loadSettings = async () => {
  const apiKey = getFromLocalStorage("apiKey") || getFromLocalStorage("arborApiToken") || "";
  const apiHostStr = getFromLocalStorage("apiHost");
  const apiHost = apiHostStr && apiHostStr.startsWith("http") ? apiHostStr : "";
  const disableCalculationOverride = (await getFromWorkbookSettings("disableCalculationOverride")) === "true";
  const modelProvider = ((await getFromWorkbookSettings("modelProvider")) as "groq" | "openai") || "openai";
  const concurrency = parseInt(getFromLocalStorage("concurrency")) || 20;
  return { apiKey, apiHost, disableCalculationOverride, modelProvider, concurrency };
};

interface ApiKeyFormProps {
  onSaved?: (_data: ApiKeyFormInputs) => void;
  onLoaded?: () => void;
}

const ApiKeyForm: React.FC<ApiKeyFormProps> = ({ onSaved, onLoaded }) => {
  const { isDebug } = useContext(DebugContext);
  const { setIsLoading } = useContext(LayoutContext);
  const [error, setError] = useState<string>("");

  const {
    register,
    handleSubmit,
    formState: { isDirty, isSubmitting, isLoading },
    reset,
  } = useForm<ApiKeyFormInputs>({
    defaultValues: async () => await loadSettings(),
  });

  useEffect(() => {
    setIsLoading(isLoading);
    if (isLoading) return;
    onLoaded && onLoaded();
  }, [isLoading]);

  useEffect(() => {
    setError("");
  }, [isDirty]);

  const onSubmit = async (data: ApiKeyFormInputs) => {
    try {
      if (data.apiKey !== undefined) setInLocalStorage("apiKey", data.apiKey);
      if (data.apiHost !== undefined) setInLocalStorage("apiHost", data.apiHost);
      if (data.concurrency !== undefined) setInLocalStorage("concurrency", (data.concurrency || 20).toString());
      await setInWorkbookSettings("disableCalculationOverride", (!!data.disableCalculationOverride).toString());
      await setInWorkbookSettings("modelProvider", data.modelProvider);
      store.setState((prev) => ({
        ...prev,
        concurrency: data.concurrency,
      }));
      reset({
        apiKey: data.apiKey,
        apiHost: data.apiHost,
        disableCalculationOverride: data.disableCalculationOverride,
        modelProvider: data.modelProvider,
        concurrency: data.concurrency,
      });
      await getQuota(data.apiKey, data.apiHost || ARBOR_CHAT_API);
      onSaved && onSaved(data);
    } catch (error) {
      console.error("Error saving keys:", error);
      setError(error.message);
    }
  };
  return (
    <>
      <form onSubmit={handleSubmit(onSubmit)} className="w-full p-4 relative">
        <div className="mb-4">
          <h2 className="font-title font-xl mb-1">Your API key</h2>
          <p>Insert the API key generated from your account to start using ArborChat</p>
        </div>
        <TokenInput id="apiKey" register={register} placeholder="API key..." className="placeholder-color-darkGrey" />
        {isDebug && (
          <>
            <div className="md:block duration-200 whitespace-nowrap rounded-lg font-title text-sm transition-colors my-4">
              <label className="font-title text-sm mb-2 flex gap-2 items-start py-2">
                <input type="checkbox" {...register("disableCalculationOverride")} className="ml-1" />
                <span className="text-xs">Disable Calculation Manual Override</span>
              </label>
            </div>
            <HostOverrideInput id="apiHost" label="API Host Override" register={register} />
            <ModelProviderSelect register={register} hide={false} />
            <div className="mb-4">
              <div className="">
                <label htmlFor="concurrency" className="items-center font-title text-sm mb-2">
                  Concurrency
                </label>
                <input
                  className={`placeholder-color-lightGrey w-full rounded border border-lightGrey p-3 pr-14`}
                  type="text"
                  id="concurrency"
                  {...register("concurrency")}
                />
              </div>
            </div>
          </>
        )}
        <div className="duration-200 rounded font-title text-sm transition-colors mt-4">
          <button
            type="submit"
            className={`w-full rounded-lg  px-6 py-3 text-white shadow-button hover:bg-darker/80 ${
              isSubmitting ? "bg-darker/80" : "bg-darker"
            }`}
            disabled={isSubmitting}
          >
            {isSubmitting ? "Saving..." : "Confirm"}
          </button>
        </div>
      </form>
      <div className="p-4 py-2">
        <div className="flex flex-row items-center justify-center gap-1 text-royalBlue">
          <IconShieldHalf size={16} />
          <p className="text-sm">Your API key is safe</p>
        </div>
      </div>
      <Alert error={error} />
      <div className="h-[100px] w-full" />
    </>
  );
};

export default ApiKeyForm;
