import React, { useContext, useState } from "react";
import { useDiagnostics } from "../../hooks/useDiagnostics";
import { DebugContext } from "../../context";
import Alert from "../../components/Alert";
import { IconArrowRight } from "@tabler/icons-react";

export const VersionWarning = () => {
  const diagnostic = useDiagnostics();
  const { isDebug } = useContext(DebugContext);
  const [closeAlert, setCloseAlert] = useState(false);

  if (diagnostic.isVersionSupported) return null;

  return (
    <>
      {isDebug && diagnostic && (
        <div className="p-3">
          <p>Version: {diagnostic.hostVersion}</p>
          <p>Platform: {diagnostic.platform}</p>
        </div>
      )}
      {!diagnostic.isVersionSupported && (
        <Alert error="Version not supported" hide={closeAlert} onClose={() => setCloseAlert(true)}>
          <p>
            Your current Excel version does not support the full functionality of ArborChat. Certain features may be
            unavailable.
          </p>
          <a
            href="https://docs.arborchat.ai/arborchat-for-excel/troubleshooting-and-error-handling"
            target="_blank"
            rel="noopener noreferrer"
            className="cursor-pointer inline-flex flex-row pt-2 items-center gap-1"
          >
            <span>See More</span>
            <IconArrowRight size={16} />
          </a>
        </Alert>
      )}
    </>
  );
};
