/* global setTimeout */

const toAddress = (rangeAddress: string, colIndex: number, rowIndex: number) => {
  const [start] = rangeAddress.split(":");
  const startCol = start.match(/^[A-Z]+/)?.[0];
  const startColIndex = base26ToDecimal(startCol);
  const startRow = parseInt(start.match(/\d+$/)?.[0] ?? "0");

  const col = decimalToBase26(startColIndex + colIndex);
  return `${col}${startRow + rowIndex}`;
};

function decimalToBase26(n) {
  let result = "";
  while (n >= 0) {
    const remainder = n % 26; // Get the remainder
    result = String.fromCharCode(remainder + "A".charCodeAt(0)) + result; // Convert to character
    n = Math.floor(n / 26) - 1; // Adjust n for the next iteration
  }
  return result;
}

function base26ToDecimal(str) {
  let n = 0;
  for (let i = str.length - 1; i >= 0; i--) {
    const value = str[i].charCodeAt(0) - "A".charCodeAt(0);
    if (i === str.length - 1) {
      n += value;
    } else {
      n += (value + 1) * Math.pow(26, str.length - i - 1);
    }
  }
  return n;
}

export const calculateCellInUsed = async () => {
  return Excel.run(async (context) => {
    const activeSheet = context.workbook.worksheets.getActiveWorksheet();
    const range = activeSheet.getUsedRange();
    range.load("formulas");
    range.load("addressLocal");
    range.load("text");
    await context.sync();

    const addressLocal = range.addressLocal.split("!")[1];

    const errorAddress = [];
    const formulaAddress = [];

    const text = range.text;

    range.formulas.forEach((row, rowIndex) => {
      row.forEach(async (colFormula, colIndex) => {
        const isArborFormula =
          colFormula &&
          colFormula?.startsWith &&
          (colFormula?.startsWith("=ARBOR_") || colFormula?.startsWith("{=ARBOR_"));
        if (isArborFormula) {
          const cellText = text[rowIndex][colIndex];
          if (cellText.startsWith("#") && (cellText.endsWith("!") || cellText.endsWith("?"))) {
            errorAddress.push(toAddress(addressLocal, colIndex, rowIndex));
          } else {
            formulaAddress.push(toAddress(addressLocal, colIndex, rowIndex));
          }
        }
      });
    });
    return {
      error: errorAddress,
      formula: formulaAddress,
      all: [...errorAddress, ...formulaAddress],
    };
  }).catch((error) => {
    console.error(error);
  });
};

export const getSelectedRanges = async () => {
  return await Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    const range = context.workbook.getSelectedRange();
    sheet.load("name");
    range.load("address");
    await context.sync();
    return [range.address.replace(`${sheet.name}!`, "")];
  })
    .catch(async (err) => {
      console.error(err);
      return Excel.run(async (context) => {
        const sheet = context.workbook.worksheets.getActiveWorksheet();
        const range = context.workbook.getSelectedRanges();
        sheet.load("name");
        range.load("address");
        await context.sync();
        return range.address.split(",").map((r) => r.replace(`${sheet.name}!`, ""));
      });
    })
    .catch((error) => {
      console.error(error);
      throw error;
    });
};

export const storeValues = async (addresses: string[]) => {
  if (!addresses.length) return;
  await Excel.run(async (context) => {
    const activeSheet = context.workbook.worksheets.getActiveWorksheet();
    const ranges = activeSheet.getRanges(addresses.join(","));
    ranges.load("areas");
    await context.sync();
    const areas = ranges.areas;
    areas.items.forEach((range) => {
      range.load("valuesAsJson");
      range.load("hasSpill");
    });
    await context.sync();
    for (const range of areas.items) {
      range.valuesAsJson = [...range.valuesAsJson];
    }
    await context.sync();
  }).catch((error) => {
    console.error(error);
    throw error;
  });
};

export const calculateCells = async (addresses: string[]) => {
  if (!addresses.length) return;
  await Excel.run(async (context) => {
    const activeSheet = context.workbook.worksheets.getActiveWorksheet();
    const ranges = activeSheet.getRanges(addresses.join(","));
    ranges.load("areas");
    await context.sync();
    const areas = ranges.areas;
    areas.items.forEach((range) => {
      range.load("formulas");
    });
    await context.sync();
    areas.items.forEach((range) => {
      const formulas = range.formulas;
      formulas.forEach((row, rowIndex) => {
        row.forEach((formula, colIndex) => {
          if (formula.startsWith("=ARBOR_")) {
            const cell = range.getCell(rowIndex, colIndex);
            cell.calculate();
          }
        });
      });
    });
    await context.sync();
  }).catch((error) => {
    console.error(error);
    throw error;
  });
};

export const addressesToRangeString = (addresses: string[]) => {
  const mapping: Record<
    string,
    Array<{
      from: number;
      to: number;
    }>
  > = {};

  addresses.forEach((address) => {
    const [from, to] = address.split(":");
    const col = from.match(/^[A-Z]+/)?.[0];
    const rowFrom = parseInt(from.match(/\d+$/)?.[0] ?? "0");
    const rowTo = to ? parseInt(to.match(/\d+$/)?.[0] ?? "0") : rowFrom;

    if (!mapping[col]) {
      mapping[col] = [{ from: rowFrom, to: rowTo }];
      return;
    }
    let findMatch = false;
    mapping[col].forEach((records) => {
      if (findMatch) return;

      if (records.from <= rowFrom && records.to >= rowTo) {
        findMatch = true;
        return;
      }

      if (rowFrom <= records.from && rowTo >= records.to) {
        records.from = rowFrom;
        records.to = rowTo;
        findMatch = true;
        return;
      }

      if (records.from <= rowFrom && records.to + 1 >= rowFrom) {
        records.to = rowTo;
        findMatch = true;
        return;
      }

      if (records.from - 1 <= rowTo && records.to >= rowTo) {
        records.from = rowFrom;
        findMatch = true;
        return;
      }
    });
    if (!findMatch) {
      mapping[col].push({ from: rowFrom, to: rowTo });
    }
  });

  // Combine consecutive single cells into ranges

  return Object.entries(mapping)
    .map(([col, records]) => {
      return records
        .map((record) => {
          if (record.from === record.to) {
            return `${col}${record.from}`;
          }
          return `${col}${record.from}:${col}${record.to}`;
        })
        .join(",");
    })
    .join(",")
    .split(",")
    .map((v) => v.trim());
};

export const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));
