import React, { useState, useCallback, useEffect, useContext } from "react";
import classNames from "classnames";
import { getFromWorkbookSettings, setInWorkbookSettings } from "../taskpane";
import { LayoutContext } from "../context";

const ManualSettingsPage: React.FC = () => {
  const [isManualCalculation, setIsManualCalculation] = useState(true);
  const { isLoading, setIsLoading } = useContext(LayoutContext);

  useEffect(() => {
    setIsLoading(true);
    getFromWorkbookSettings("disableCalculationOverride").then((value) => {
      setIsManualCalculation(!(value === "true"));
      setIsLoading(false);
    });
  }, []);

  const onToggleManualCalculation = useCallback(async () => {
    const value = !isManualCalculation;
    setIsManualCalculation(value);
    await setInWorkbookSettings("disableCalculationOverride", (!value).toString());
  }, [isManualCalculation]);

  if (isLoading) return null;

  return (
    <div className="p-4">
      <h1 className="py-2">Manual Settings</h1>
      <div className="flex flex-row gap-2 justify-between items-center rounded bg-lightGrey p-3 mt-4">
        <span className="font-title text-sm tracking-tight">Manual Regeneration</span>
        <button
          className={classNames("rounded-full w-[40px] h-[24px] relative hover:bg-grey/80", {
            "bg-grey": !isManualCalculation,
            "bg-green": isManualCalculation,
          })}
          onClick={onToggleManualCalculation}
        >
          <div
            className={classNames("rounded-full absolute transition-all top-0 duration-200 p-1", {
              "left-0": !isManualCalculation,
              "left-[calc(100%-24px)]": isManualCalculation,
            })}
          >
            <div className="w-[16px] h-[16px] rounded-full bg-white"></div>
          </div>
        </button>
      </div>
      <p className="mt-4 text-darkGrey">
        Whenever a related cell is modified or the sheet is reopened, all ArborChat formulas will automatically
        recalculate, triggering the generation of new data and potentially consuming additional tokens.
      </p>
      <p className="mt-4 text-darkGrey">
        Switching to Manual Calculation mode to prevent unintended recalculations is recommended. This allows you to
        control when formulas are updated, optimizing token usage and improving performance.
      </p>
    </div>
  );
};

export default ManualSettingsPage;
