/* global setTimeout, clearTimeout */

import React, { useState, useEffect, useCallback } from "react";
import ApiKeyForm from "../../components/ApiKeyForm";
import { useNavigate } from "react-router-dom";
import HoverLayer from "./HoverLayer";
import GitBookFooter from "../../components/GitBookFooter";

const Onboarding: React.FC = () => {
  const navigate = useNavigate();
  const [showHoverLayer, setShowHoverLayer] = useState(true);
  const [formLoaded, setFormLoaded] = useState(false);

  useEffect(() => {
    const timer = setTimeout(() => {
      setShowHoverLayer(false);
    }, 1000);

    return () => clearTimeout(timer);
  }, []);

  const onLoaded = useCallback(() => {
    setFormLoaded(true);
  }, []);

  const onFormSaved = useCallback(async () => {
    navigate("/");
  }, []);

  return (
    <>
      <HoverLayer show={showHoverLayer || !formLoaded} />
      <div className="p-4">
        <h1 className="mt-4">Welcome to ArborChat for Excel</h1>
      </div>
      <ApiKeyForm onLoaded={onLoaded} onSaved={onFormSaved} />
      <GitBookFooter />
    </>
  );
};

export default Onboarding;
