import React, { useCallback } from "react";
import { addressesToRangeString } from "../../utils";

interface NumberStatsProps {
  cellList: string[];
  label: string;
  color: string;
  isDisabled: boolean;
  // eslint-disable-next-line no-unused-vars
  onValueClick: (value: string) => void;
}

const NumberStats: React.FC<NumberStatsProps> = ({ cellList, label, color, onValueClick }) => {
  const onValueClickHandler = useCallback(() => {
    const cellAddresses = addressesToRangeString(cellList).join(", ");
    onValueClick && onValueClick(cellAddresses);
  }, [onValueClick, cellList]);

  return (
    <div className="flex flex-row my-1 items-center flex-1 justify-center gap-1">
      <button
        className={`text-${color} text-lg leading-[20px] font-title tracking-title`}
        onClick={onValueClickHandler}
      >
        {cellList.length}
      </button>
      <span className="text-sm font-title tracking-title">{label}</span>
    </div>
  );
};

export default NumberStats;
