import store from "../../stores/store";
import { calculateCells, delay } from "../utils";

import { useCallback, useState } from "react";

export const useCellRegeneration = (isDisabled?: boolean) => {
  const [isLoading, setIsLoading] = useState(false);

  const onRegenerate = useCallback(
    async (cellList: string[]) => {
      if (isDisabled) return;
      setIsLoading(true);
      if (cellList.length) {
        await calculateCells(cellList);
      }
      await delay(500);
      setIsLoading(false);
    },
    [isDisabled]
  );

  const onAbort = useCallback(() => {
    store.abortAllRequests();
  }, []);

  return { onRegenerate, onAbort, isLoading };
};
